// Read payload
const data = msg.payload;

// Validation checks
if (data.serialId === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "serialId is required"
    };
    return [null, msg];
}

if (!Array.isArray(data.Panels)) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Panels must be an array"
    };
    return [null, msg];
}

if (data.PanelCount !== data.Panels.length) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "PanelCount does not match Panels length"
    };
    return [null, msg];
}

if (typeof data.thickness !== "number") {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Thickness must be numeric"
    };
    return [null, msg];
}

// Validation successful
return [msg, null];

const input = msg.payload;

let workItems = [];

for(let panel of input.Panels){

    workItems.push({

        serialId: input.serialId,

        panel: panel,

        thickness: input.thickness

    });

}

msg.payload = workItems;

return msg;

const rules = global.get("thicknessRules");

const thickness = msg.payload.thickness;

let selectedRule = null;

for(const rule of rules){

    if(thickness >= rule.min &&
       thickness < rule.max){

        selectedRule = rule;

        break;

    }

}

if(selectedRule == null){

    node.error("No matching thickness rule");

    return null;

}

msg.rule = selectedRule;

return msg;

