function randomBetween(min, max) {
    return +(Math.random() * (max - min) + min).toFixed(2);
}

const calculators = {

    P1: (thickness) => {

        if (thickness >= 0 && thickness < 1)
            return randomBetween(10, 20);

        if (thickness >= 1 && thickness < 2)
            return randomBetween(25, 35);

        return null;
    },

    P2: (thickness) => {

        if (thickness >= 0 && thickness < 0.8)
            return randomBetween(100, 150);

        if (thickness >= 0.8 && thickness < 3)
            return randomBetween(180, 220);

        return null;
    },

    P3: (thickness) => {

        if (thickness >= 0.5 && thickness < 1.5)
            return randomBetween(500, 600);

        if (thickness >= 1.5 && thickness <= 3)
            return randomBetween(700, 800);

        return null;
    },

    P4: (thickness) => {

        if (thickness >= 0.5 && thickness < 1.5)
            return randomBetween(500, 600);

        if (thickness >= 1.5 && thickness <= 3)
            return randomBetween(700, 800);

