    },

    P8: (thickness) => {

        if (thickness >= 0.5 && thickness < 1.5)
            return randomBetween(500, 600);

        if (thickness >= 1.5 && thickness <= 3)
            return randomBetween(700, 800);

        return null;
    },

    P9: (thickness) => {

        if (thickness >= 0.5 && thickness < 1.5)
            return randomBetween(500, 600);

        if (thickness >= 1.5 && thickness <= 3)
            return randomBetween(700, 800);

        return null;
    }

};

const thickness = msg.payload.thickness;
const calculated = {};

for (const parameter of msg.rule.parameters) {

    if (calculators[parameter]) {

        calculated[parameter] = calculators[parameter](thickness);

    }

}

msg.parameters = calculated;

return msg;

const result = {};

result.serialId = msg.payload.serialId;

result[msg.payload.panel] = msg.parameters;

msg.payload = result;

return msg;

const rules = [

    {
        min: 0,
        max: 1,

        parameters: [
            "P1",
            "P2",
            "P3"
        ]
    },

    {
        min: 1,
        max: 3,

        parameters: [
            "P4",
            "P5",
            "P6",
            "P7"
        ]
    },

    {
        min: 3,
        max: 10,

        parameters: [
            "P8",
            "P9",
            "P10"
        ]
    }

];

global.set("thicknessRules", rules);

node.status({
    fill: "green",
    shape: "dot",
    text: "Rules Loaded"
});

return null;
